def create_cloned_field(field, *, cloned_types=None):
    cloned_types = cloned_types or {}
    original_type = getattr(field.type_, "__pydantic_model__", field.type_)

    if is_dataclass(original_type) and hasattr(original_type, "__pydantic_model__"):
        original_type = original_type.__pydantic_model__

    if lenient_issubclass(original_type, BaseModel):
        original_type = cast(Type[BaseModel], original_type)
        use_type = cloned_types.get(original_type)
        if use_type is None:
            use_type = create_model(original_type.__name__, __base__=original_type)
            cloned_types[original_type] = use_type
            use_type.__fields__ = {
                f.name: create_cloned_field(f, cloned_types=cloned_types)
                for f in original_type.__fields__.values()
            }
    else:
        use_type = original_type

    new_field = create_response_field(name=field.name, type_=use_type)

    # Copy attributes
    for attr in [
        "has_alias", "alias", "class_validators", "default",
        "required", "model_config", "field_info",  "allow_none", 
        "validate_always", "validators", "pre_validators", 
        "post_validators", "parse_json", "shape"
    ]:
        setattr(new_field, attr, getattr(field, attr))

    # Recursively clone sub_fields if they exist
    new_field.sub_fields = [
        create_cloned_field(sub_field, cloned_types=cloned_types)
        for sub_field in getattr(field, "sub_fields", [])
    ]

    # Recursively clone key_field if it exists
    if field.key_field:
        new_field.key_field = create_cloned_field(field.key_field, cloned_types=cloned_types)

    # Automatically populate validators based on the updated configuration
    new_field.populate_validators()
    return new_field

