def update_state(
    self, session=NEW_SESSION, execute_callbacks=True
):
    class _UnfinishedStates(NamedTuple):
        def calculate(cls, unfinished_tis):
            return cls(tis=unfinished_tis)
        def should_schedule(self):
            return (
                self.tis
                and all(not t.task.depends_on_past for t in self.tis)
                and all(t.task.max_active_tis_per_dag is None for t in self.tis)
                and all(t.task.max_active_tis_per_dagrun is None for t in self.tis)
                and all(t.state != TaskInstanceState.DEFERRED for t in self.tis)
            )
        def recalculate(self):
            return self._replace(tis=[t for t in self.tis if t.state in State.unfinished])

    start_dttm = timezone.utcnow()
    self.last_scheduling_decision = start_dttm
    callback = None

    with Stats.timer(f"dagrun.dependency-check.{self.dag_id}", tags=self.stats_tags):
        dag = self.get_dag()
        info = self.task_instance_scheduling_decisions(session)
        tis, schedulable_tis, changed_tis, finished_tis = info.tis, info.schedulable_tis, info.changed_tis, info.finished_tis
        unfinished = _UnfinishedStates.calculate(info.unfinished_tis)
        if unfinished.should_schedule:
            are_runnable_tasks = bool(schedulable_tis or changed_tis)
            if not are_runnable_tasks:
                are_runnable_tasks, changed_by_upstream = self._are_premature_tis(unfinished.tis, finished_tis, session)
                if changed_by_upstream:
                    unfinished = unfinished.recalculate()

    leaf_task_ids = {t.task_id for t in dag.leaves}
    leaf_tis = {ti for ti in tis if ti.task_id in leaf_task_ids and ti.state != TaskInstanceState.REMOVED}

    if dag.teardowns:
        teardown_task_ids = {t.task_id for t in dag.teardowns}
        upstream_of_teardowns = {t.task_id for t in dag.tasks_upstream_of_teardowns}
        teardown_tis = {ti for ti in tis if ti.task_id in teardown_task_ids}
        on_failure_fail_tis = {ti for ti in teardown_tis if ti.task.on_failure_fail_dagrun}
        tis_upstream_of_teardowns = {ti for ti in tis if ti.task_id in upstream_of_teardowns}
        leaf_tis.difference_update(teardown_tis)
        leaf_tis.update(on_failure_fail_tis)
        leaf_tis.update(tis_upstream_of_teardowns)

    failure_conditions = not unfinished.tis and any(leaf_ti.state in State.failed_states for leaf_ti in leaf_tis)
    success_conditions = not unfinished.tis and all(leaf_ti.state in State.success_states for leaf_ti in leaf_tis)
    deadlock_conditions = unfinished.should_schedule and not are_runnable_tasks

    if failure_conditions:
        message, state, success = ("task_failure", DagRunState.FAILED, False)
    elif success_conditions:
        message, state, success = ("success", DagRunState.SUCCESS, True)
    elif deadlock_conditions:
        message, state, success = ("all_tasks_deadlocked", DagRunState.FAILED, False)
    else:
        self.set_state(DagRunState.RUNNING)
        return schedulable_tis, callback

    self.log.error(f"Marking run {self} {message}", self)
    self.set_state(state)
    self.notify_dagrun_state_changed(msg=message)

    if execute_callbacks:
        dag.handle_callback(self, success=success, reason=message, session=session)
